import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] a = new long[n];
        long hi = 1;
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
            hi = Math.max(hi, a[i]);
        }
        long hours = nextLong();
        if (hours < n) { // every pile needs at least one unit of time
            System.out.println(-1);
            return;
        }
        // Binary search the smallest speed whose total of ceil(a / speed) fits in the deadline.
        long lo = 1;
        while (lo < hi) {
            long mid = (lo + hi) / 2, total = 0;
            for (long v : a) total += (v + mid - 1) / mid;
            if (total <= hours) hi = mid;
            else lo = mid + 1;
        }
        System.out.println(lo);
    }
}

