import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n := int(nextInt())
	a := make([]int64, n)
	hi := int64(1)
	for i := range a {
		a[i] = nextInt()
		hi = max(hi, a[i])
	}
	hours := nextInt()
	if hours < int64(n) { // every pile needs at least one unit of time
		fmt.Println(-1)
		return
	}
	// Binary search the smallest speed whose total of ceil(a / speed) fits in the deadline.
	lo := int64(1)
	for lo < hi {
		mid, total := (lo+hi)/2, int64(0)
		for _, v := range a {
			total += (v + mid - 1) / mid
		}
		if total <= hours {
			hi = mid
		} else {
			lo = mid + 1
		}
	}
	fmt.Println(lo)
}
